public void doSaveCatalog(SpsCatalogSyncTask task) {
    // 进入即置「处理中」，防止 60 秒扫描器再捞一次
    updateTaskStatus(task.getId(), TASK_STATUS_PROCESSING, null);
    try {
        SpsSaveResult result = spsRestClient.saveCatalog(task.getRequestBody());
        if (!result.isSuccess()) {
            throw new BizException(result.getMsg());
        }
        updateTaskStatus(task.getId(), TASK_STATUS_DONE, null);
    } catch (Exception e) {
        int attempt = task.getAttempt() == null ? 0 : task.getAttempt();
        // 按 task_type + task_status 回滚，避免把别的定时任务也改回 0
        int rows = syncTaskDao.rollbackToPending(task.getId(), TASK_TYPE_SPS_CATALOG,
                TASK_STATUS_PROCESSING, attempt + 1,
                "第 " + (attempt + 1) + " 次失败：" + shorten(e.getMessage()));
        log.error("saveCatalog failed, rollback rows: {}, taskId: {}", rows, task.getId(), e);
        sleepBackoff(attempt + 1);
    }
}

public SpsSaveResult saveCatalog(String requestBody) {
    long start = System.currentTimeMillis();
    try {
        ResponseEntity<String> resp = restTemplate.postForEntity(SAVE_URL,
                buildEntity(requestBody), String.class);
        long cost = System.currentTimeMillis() - start;
        SpsResponse body = JSON.parseObject(resp.getBody(), SpsResponse.class);
        if (body == null) {
            log.error("sps saveCatalog empty body, cost: {}ms, reqSummary: {}",
                    cost, summary(requestBody));
            return SpsSaveResult.fail("上游返回为空，请稍后重试");
        }
        if (!SUCCESS_CODE.equals(body.getCode())) {
            log.error("sps saveCatalog biz fail, cost: {}ms, code: {}, msg: {}, reqSummary: {}",
                    cost, body.getCode(), body.getMsg(), summary(requestBody));
            return SpsSaveResult.fail("同步失败：" + body.getMsg());
        }
        return SpsSaveResult.ok();
    } catch (ResourceAccessException e) {
        log.error("sps saveCatalog io error, cost: {}ms, reqSummary: {}",
                System.currentTimeMillis() - start, summary(requestBody), e);
        return SpsSaveResult.fail("连不上配单系统，请稍后重试");
    } catch (Exception e) {
        log.error("sps saveCatalog unexpected, reqSummary: {}", summary(requestBody), e);
        return SpsSaveResult.fail("同步异常，请联系管理员");
    }
}
